using System;using System.IO;using System.Linq;using System.Text;using System.Windows.Media.Media3D;
namespace GearLab {public static class Gripper671CoreTests {
 public static int Run(string folder){Directory.CreateDirectory(folder);int checks=0;Action<bool,string> check=(b,m)=>{checks++;if(!b)throw new Exception(m);};try{var d=ReferenceRobot67.Cached();var b=RobotCad.Build(d);check(b.Model.Valid,"current assembly");var terminal=d.Joints.Last();var movable=b.Entries.Values.Where(e=>e.GripperSide!=0).ToArray();check(movable.Length==8,"eight moving gripper parts");var parts=b.Entries.ToDictionary(e=>e.Key,e=>e.Value.Part);var initial=parts.ToDictionary(e=>e.Key,e=>e.Value.Placement);var fingerprints=d.Joints.Select(j=>j.GeneratedBody.Fingerprint).ToArray();var pose=d.Joints.Select(j=>j.Position).ToArray();foreach(double opening in new[]{0.0,2,12,26,40}){d.GripperOpening=opening;foreach(var e in movable){var local=e.Local;local.Translate(e.GripperSlide*((opening-e.GripperReferenceOpening)/2));check(b.Pose(e.Id,0,false)==local*b.Current[terminal.Id].Output,"live opening transform");}check(d.Joints.Select(j=>j.Position).SequenceEqual(pose),"arm pose unchanged");check(d.Joints.Select(j=>j.GeneratedBody.Fingerprint).SequenceEqual(fingerprints),"native fingerprints unchanged");var snapshot=b.ForExport(false,null);foreach(var e in movable)check(snapshot.Parts.Single(p=>p.Id==e.Id).Placement==b.Pose(e.Id,0,false),"export current opening");check(b.Entries.All(e=>ReferenceEquals(parts[e.Key],e.Value.Part)&&e.Value.Part.Placement==initial[e.Key]),"export leaves original CAD objects untouched");}d.GripperOpening=41;check(d.Validate().Any(),"invalid opening rejected");File.WriteAllText(Path.Combine(folder,"gripper671-core-results.txt"),"PASS "+checks+" assertions: cached geometry, local jaw motion, arm pose, current export, validation.",Encoding.UTF8);return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"gripper671-core-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}}
}}
